[CmdletBinding()]
param(
  # Project folder where template files have already been copied.
  [Parameter(Mandatory = $true)]
  [string]$DestinationFolder,

  # Explicit VS Code workspace folder that owns the new project.
  [Parameter(Mandatory = $true)]
  [string]$WorkspaceRoot,

  # ArcGIS Pro install path used by project references and DAML placeholders.
  [Parameter(Mandatory = $true)]
  [string]$ProInstallDir,

  # Installed ArcGIS Pro product version string from detection step.
  [Parameter(Mandatory = $true)]
  [string]$ArcGISProVersion,

  # Sanitized project identifier generated by naming step.
  [Parameter(Mandatory = $true)]
  [string]$SafeProjectName,

  # Project type determines which available tokens are required by the selected template.
  [Parameter(Mandatory = $true)]
  [ValidateSet('Addin', 'Configuration', 'CoreHost', 'PluginDatasource')]
  [string]$ProjectType
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# ==============================
# Input Validation
# ==============================
if (-not (Test-Path -Path $DestinationFolder -PathType Container)) {
  throw "Destination folder does not exist: $DestinationFolder"
}

if (-not (Test-Path -LiteralPath $WorkspaceRoot -PathType Container)) {
  throw "WorkspaceRoot must be an existing VS Code workspace folder: $WorkspaceRoot"
}

$WorkspaceRoot = (Resolve-Path -LiteralPath $WorkspaceRoot).Path
$DestinationFolder = (Resolve-Path -LiteralPath $DestinationFolder).Path
$workspaceRootPrefix = $WorkspaceRoot.TrimEnd(
  [System.IO.Path]::DirectorySeparatorChar,
  [System.IO.Path]::AltDirectorySeparatorChar
) + [System.IO.Path]::DirectorySeparatorChar
if (-not $DestinationFolder.StartsWith($workspaceRootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
  throw "Destination folder must be inside the VS Code workspace folder: $WorkspaceRoot"
}
$workspaceRelativeProjectPath = $DestinationFolder.Substring($workspaceRootPrefix.Length) -replace '\\', '/'

# Canonicalize once before deriving values for XML and JSON files.
$ProInstallDir = $ProInstallDir.TrimEnd(
  [System.IO.Path]::DirectorySeparatorChar,
  [System.IO.Path]::AltDirectorySeparatorChar
)
$damlInstallDir = ($ProInstallDir -replace '\\', '/').TrimEnd('/') + '/'
$proInstallDirJson = ($ProInstallDir -replace '\\', '/').TrimEnd('/')

# Extract major.minor for templates that pin desktop version compatibility.
$versionMatch = [regex]::Match($ArcGISProVersion, '^(?<major>\d+)\.(?<minor>\d+)')
if (-not $versionMatch.Success) {
  throw "ArcGISProVersion is not in a recognized format: $ArcGISProVersion"
}
$versionMajorMinor = "{0}.{1}" -f $versionMatch.Groups['major'].Value, $versionMatch.Groups['minor'].Value

# Generate one-time values per run for reproducible token replacement within this invocation.
$dateValue = (Get-Date).ToString('M/d/yyyy h:mm:ss tt')
$newIdValue = "{$([guid]::NewGuid().ToString())}"

# ==============================
# Substitution Map
# ==============================
# Ordered map keeps replacement output stable.
$substitutions = [ordered]@{
  ProInstallDir   = $ProInstallDir
  ProInstallDirJson = $proInstallDirJson
  ArcGISProVersion = $ArcGISProVersion
  SafeProjectName = $SafeProjectName
  WorkspaceRelativeProjectPath = $workspaceRelativeProjectPath
  DamlInstallDir  = $damlInstallDir
  Date            = $dateValue
  NewID           = $newIdValue
  VersionMajorMinor = $versionMajorMinor
}

# ==============================
# Encoding Helpers
# ==============================
# Preserve each file's original text encoding when writing updated content.
function Get-FileEncoding {
  param([Parameter(Mandatory = $true)][string]$Path)

  $stream = [System.IO.File]::OpenRead($Path)
  try {
    $reader = New-Object System.IO.StreamReader($stream, $true)
    try {
      [void]$reader.Peek()
      return $reader.CurrentEncoding
    } finally {
      $reader.Dispose()
    }
  } finally {
    $stream.Dispose()
  }
}

# File types that may contain template tokens.
$textExtensions = @(
  '.daml', '.json', '.xml', '.cs', '.xaml', '.csproj',
  '.config', '.props', '.targets', '.resx', '.txt', '.md',
  '.yml', '.yaml', '.editorconfig', '.sln', '.cmd', '.ps1'
)

# ==============================
# Replacement Scan And Apply
# ==============================
$filesScanned = 0
$filesUpdated = 0
$replacementCounts = @{}
$updatedFiles = New-Object System.Collections.Generic.List[string]
$remainingTokenHits = New-Object System.Collections.Generic.List[object]
$scanRoots = New-Object System.Collections.Generic.List[string]
$seenScanRoots = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

foreach ($root in @($DestinationFolder, (Join-Path -Path $WorkspaceRoot -ChildPath '.vscode'))) {
  if (-not (Test-Path -Path $root -PathType Container)) {
    continue
  }

  $resolvedRoot = (Resolve-Path -Path $root).Path
  if ($seenScanRoots.Add($resolvedRoot)) {
    $scanRoots.Add($resolvedRoot) | Out-Null
  }
}

Get-ChildItem -Path $scanRoots -Recurse -File | ForEach-Object {
  $file = $_
  $ext = [System.IO.Path]::GetExtension($file.FullName)
  # Skip binary/unknown file types to avoid content corruption.
  if (-not ($textExtensions -contains $ext.ToLowerInvariant())) {
    return
  }

  $filesScanned++

  $original = [System.IO.File]::ReadAllText($file.FullName)
  # Short-circuit files that do not contain placeholder syntax.
  if ($original -notmatch '\{\{[^}]+\}\}') {
    return
  }

  $updated = $original
  foreach ($name in $substitutions.Keys) {
    $pattern = "\{\{$([regex]::Escape($name))\}\}"
    $matchCount = [regex]::Matches($updated, $pattern).Count
    if ($matchCount -gt 0) {
      if (-not $replacementCounts.ContainsKey($name)) {
        $replacementCounts[$name] = 0
      }
      $replacementCounts[$name] += $matchCount

      # Replace all instances of a token in the current file snapshot.
      $updated = [regex]::Replace($updated, $pattern, [string]$substitutions[$name])
    }
  }

  if ($updated -ne $original) {
    $encoding = Get-FileEncoding -Path $file.FullName
    [System.IO.File]::WriteAllText($file.FullName, $updated, $encoding)
    $filesUpdated++
    $updatedFiles.Add($file.FullName) | Out-Null
  }

  # Capture unresolved placeholders for diagnostics and downstream validation.
  $remaining = @([regex]::Matches($updated, '\{\{[^}]+\}\}') | ForEach-Object { $_.Value } | Sort-Object -Unique)
  if ($remaining.Length -gt 0) {
    $remainingTokenHits.Add([pscustomobject]@{
      FilePath = $file.FullName
      Tokens   = $remaining
    }) | Out-Null
  }
}

# Tokens not used by the selected template are informational, not failures.
$requiredTokensByProjectType = @{
  Addin            = @('ProInstallDir', 'ProInstallDirJson', 'ArcGISProVersion', 'SafeProjectName', 'WorkspaceRelativeProjectPath', 'DamlInstallDir', 'Date', 'NewID')
  Configuration    = @('ProInstallDir', 'ProInstallDirJson', 'ArcGISProVersion', 'SafeProjectName', 'WorkspaceRelativeProjectPath', 'DamlInstallDir', 'Date', 'NewID')
  CoreHost         = @('ProInstallDir', 'SafeProjectName', 'WorkspaceRelativeProjectPath')
  PluginDatasource = @('ProInstallDir', 'ProInstallDirJson', 'SafeProjectName', 'WorkspaceRelativeProjectPath', 'DamlInstallDir', 'Date', 'NewID', 'VersionMajorMinor')
}
$requiredTokensMissing = @()
foreach ($name in $requiredTokensByProjectType[$ProjectType]) {
  if (-not $replacementCounts.ContainsKey($name)) {
    $requiredTokensMissing += $name
  }
}

$unusedAvailableTokens = @()
foreach ($name in $substitutions.Keys) {
  if (-not $replacementCounts.ContainsKey($name)) {
    $unusedAvailableTokens += $name
  }
}

# ==============================
# Output Contract
# ==============================
[pscustomobject]@{
  DestinationFolder     = (Resolve-Path -Path $DestinationFolder).Path
  WorkspaceRelativeProjectPath = $workspaceRelativeProjectPath
  ScannedRoots          = $scanRoots
  DamlInstallDir        = $damlInstallDir
  ProInstallDirJson     = $proInstallDirJson
  VersionMajorMinor     = $versionMajorMinor
  Date                  = $dateValue
  NewID                 = $newIdValue
  FilesScanned          = $filesScanned
  FilesUpdated          = $filesUpdated
  ReplacementsByToken   = $replacementCounts
  RequiredTokensMissing = $requiredTokensMissing
  UnusedAvailableTokens = $unusedAvailableTokens
  UnresolvedTokens      = $remainingTokenHits
  UpdatedFiles          = $updatedFiles
}
